#include "stdafx.h"#include <rsuNoNames.h>#include "H_Server.h"#include <rsuErr.h>#ifdef _MANAGED#pragma managed(push, off)#endifHINSTANCE g_hInst = 0;BOOL APIENTRY DllMain( HMODULE hModule,                       DWORD  ul_reason_for_call,                       LPVOID lpReserved					 ){  switch (ul_reason_for_call)  {  case DLL_PROCESS_ATTACH:    g_hInst = hModule;    LoadLibrary("H5xxServerMemCtrl.dll");    break;  case DLL_THREAD_ATTACH:  case DLL_THREAD_DETACH:  case DLL_PROCESS_DETACH:    break;  }  return TRUE;}#ifdef _MANAGED#pragma managed(pop)#endifstatic FILE *pLog = NULL;KNoName g_Objs, g_IOs, g_IOsObjsInfo;static CBase* _ObjsStructAllocatorImpl( LPCSTR ObjName, DWORD TypeID, int number ){  if( !pLog )  {    char szPath[MAX_PATH];    _makepath_s( szPath, NULL, rsuGetMemoryPath(), "HW5tegs", "csv" );    fopen_s( &pLog, szPath, "wt" );  }  if( pLog )  {    fprintf_s( pLog, "%s;%d\n", ObjName, TypeID );    fflush( pLog );  }  CBase *pObj = g_Objs.CreateStruct( ObjName, TypeID, number );  if( pObj && 0==number )  {    SPntTypeInfo *pInfo = (SPntTypeInfo*)g_IOsObjsInfo.CreateStruct( ObjName, id_PntTypeInfo, 0 );    if( pInfo )    {      //ASSD( !pInfo->realTypeID );      if( pInfo->realTypeID )      {        OutputDebugString("Уже существует "); OutputDebugString(ObjName);OutputDebugString("\n");      }      pInfo->realTypeID = TypeID;      pInfo->pntID = pObj->ID_PNT_NAME;      pInfo->classID = pObj->ID_CLASS;      pInfo->nObjOrIO = SPntTypeInfo::entObj;    }  }  return pObj;}static CBase* _IOsStructAllocatorImpl( LPCSTR ObjName, DWORD TypeID, int number ){  if( !pLog )  {    char szPath[MAX_PATH];    _makepath_s( szPath, NULL, rsuGetMemoryPath(), "HW5tegs", "csv" );    fopen_s( &pLog, szPath, "wt" );  }  if( pLog )  {    fprintf_s( pLog, "%s;%d\n", ObjName, TypeID );    fflush( pLog );  }  return g_IOs.CreateStruct( ObjName, TypeID, number );}static int _RefIoCreator( LPCSTR ObjName, CBase *pBase, DWORD TypeID ){  if( !pLog )  {    char szPath[MAX_PATH];    _makepath_s( szPath, NULL, rsuGetMemoryPath(), "HW5tegs", "csv" );    fopen_s( &pLog, szPath, "wt" );  }  if( pLog )  {    fprintf_s( pLog, "%s;%d\n", ObjName, TypeID );    fflush( pLog );  }  return g_IOs.CreateRefToData( ObjName, pBase );}static CBase* _StructFinder( LPCSTR ObjName, DWORD TypeID, int number ){  return g_Objs.FindStruct( ObjName, TypeID, number );}//////////////////////////////////////////////////////////////////////////static bool s_bConstructedMemory = false;extern "C" Q_DECL_DLLEXPORT      IRsuModel* CreateServer(LPCSTR ObjName ){  if( !s_bConstructedMemory )  {    g_Objs = KNoName::Create( "H5xx_Objs", true );    g_IOs = KNoName::Create( "H5xx_IOs", true );    g_IOsObjsInfo = KNoName::Create( "H5xx_Info", true );    g_Objs.Reset();    g_IOs.Reset();    g_IOsObjsInfo.Reset();    KMemoryServiceH5xx::Instance().InitObjectsStructAllocator( _ObjsStructAllocatorImpl, NULL, _StructFinder );    KMemoryServiceH5xx::Instance().InitIOsStructAllocator( _IOsStructAllocatorImpl, _RefIoCreator );    s_bConstructedMemory = true;  }  IRsuModel *pModel = new KServer( ObjName );  return pModel;}